using FluentValidation; using MediatR; using Microsoft.EntityFrameworkCore; using InventorySystem.Application.DTOs; using InventorySystem.Application.Interfaces; using InventorySystem.Domain.Entities;
namespace InventorySystem.Application.Features.Stock.Queries;
public record GetStockMovementsQuery(int? ProductId=null,int? WarehouseId=null,MovementType? Type=null,DateTime? From=null,DateTime? To=null,int Page=1,int PageSize=20) : IRequest<PagedResult<StockMovementDto>>;
public class GetStockMovementsQueryValidator : AbstractValidator<GetStockMovementsQuery> { public GetStockMovementsQueryValidator(){ RuleFor(x=>x.Page).GreaterThanOrEqualTo(1); RuleFor(x=>x.PageSize).InclusiveBetween(1,100); } }
public class GetStockMovementsQueryHandler(IAppDbContext db) : IRequestHandler<GetStockMovementsQuery,PagedResult<StockMovementDto>> { public async Task<PagedResult<StockMovementDto>> Handle(GetStockMovementsQuery r,CancellationToken ct){ var q=db.StockMovements.AsNoTracking().Where(x=>!x.IsDeleted); if(r.ProductId.HasValue) q=q.Where(x=>x.ProductId==r.ProductId.Value); if(r.WarehouseId.HasValue) q=q.Where(x=>x.WarehouseId==r.WarehouseId.Value); if(r.Type.HasValue) q=q.Where(x=>x.Type==r.Type.Value); if(r.From.HasValue) q=q.Where(x=>x.Date>=r.From.Value); if(r.To.HasValue) q=q.Where(x=>x.Date<=r.To.Value); var page=Math.Max(1,r.Page); var size=Math.Clamp(r.PageSize,1,100); var total=await q.CountAsync(ct); var items=await q.OrderByDescending(x=>x.Date).Skip((page-1)*size).Take(size).Select(x=>new StockMovementDto(x.Id,x.ProductId,x.Product.Name,x.WarehouseId,x.Warehouse.Name,x.Quantity,x.Type,x.Reference,x.Notes,x.Date)).ToListAsync(ct); return new PagedResult<StockMovementDto>(items,total,page,size); } }
